create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SVMARA_EKS_ITEM_DQ_EKS_RLZ_MHD_NOTMANTAINED_010_2(
	NEGOTIATINGCOUNTRY,
	BUYERSHORTSIGN,
	BUYERFIRSTNAME,
	BUYERLASTNAME,
	ZMATKL,
	ARTICLEFAMILY,
	SK_ITEMNO,
	SK_DESCRIPTION_INT,
	ITEMID,
	ITEMNO,
	ARTICLETYPE,
	DESCRIPTION,
	LISTINGOVERVIEWID,
	SUPPLIERNO,
	SUPPLIERDESCRIPTION,
	RECEIVINGCOUNTRY,
	ZRELEVANTMDM,
	ZSOURCE,
	ZACTIVE
) as
(SELECT DISTINCT EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry as NegotiatingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName, EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL, EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_ITEMNO, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_DESCRIPTION_INT, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO, EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType as ArticleType, EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT AS Description,  EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.LISTINGOVERVIEWID, SUP.INTSUPPLIERNO AS SUPPLIERNO, SUP.DESCRIPTION AS SUPPLIERDESCRIPTION, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.ReceivingCountry, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.zIsWAWIRelevant AS zRelevantMDM, EKS_CALCULATION.stMARA_EKS_ITEM.zSource, EKS_CALCULATION.stMARA_EKS_ITEM.zActive
FROM     EKS_CALCULATION.stMARA_EKS_ITEM_2 INNER JOIN
EKS_CALCULATION.xtEKS_BASICINFO_RecCountry_2 ON EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.itemid LEFT OUTER JOIN
EKS.ITEMSHELFTIME_2 AS ITS ON ITS.CONTRACTPRICEVALIDITYID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.CONTRACTPRICEVALIDITYID AND ITS.ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.itemid LEFT OUTER JOIN
EKS.SHELFTIME_2 AS SH ON SH.SHELFTIMEID = ITS.SHELFTIMEID LEFT OUTER JOIN
EKS.UNIT_2 AS UN ON UN.UNITID = SH.WHTIMEUNITID LEFT OUTER JOIN
EKS.TRANSLATION_INT_2 AS TR ON TR.TRANSLATIONID = UN.SHORTDESCID LEFT OUTER JOIN
EKS.ITEMSHELFTIME_2 AS ITS1 ON ITS1.CONTRACTPRICEVALIDITYID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.CONTRACTPRICEVALIDITYID AND ITS1.ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_ITEMID LEFT OUTER JOIN
EKS.SHELFTIME_2 AS SH1 ON SH1.SHELFTIMEID = ITS1.SHELFTIMEID LEFT OUTER JOIN
EKS.UNIT_2 AS UN1 ON UN1.UNITID = SH1.WHTIMEUNITID LEFT OUTER JOIN
EKS.TRANSLATION_INT_2 AS TR1 ON TR1.TRANSLATIONID = UN1.SHORTDESCID LEFT OUTER JOIN
EKS.SUPPLIER_2 AS SUP ON SUP.SUPPLIERNO = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SUPPLIERNO LEFT OUTER JOIN
EKS.ITEMSIGN_2 AS SIGN_EA ON SIGN_EA.ITEMID = EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.itemid
WHERE  ((CASE WHEN stMARA_EKS_ITEM.zmatkl IN ('60', '61', '63', '80', '82', '83', '84', '85', '86') THEN 1 WHEN (ArticleFamily = '44.30' AND lower(stmara_eks_item.DESCRIPTION_INT) LIKE '%essig%') THEN 1 WHEN (ArticleFamily = '81.50' AND lower(stmara_eks_item.DESCRIPTION_INT) LIKE '%streu%') THEN 1 ELSE 0 END) = 0)
GROUP BY EKS_CALCULATION.stMARA_EKS_ITEM.zNegotiatingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerSHORTSIGN, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerFirstName, EKS_CALCULATION.stMARA_EKS_ITEM.BuyerLastName, EKS_CALCULATION.stMARA_EKS_ITEM.zMATKL, EKS_CALCULATION.stMARA_EKS_ITEM.ArticleFamily, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMID, EKS_CALCULATION.stMARA_EKS_ITEM.ITEMNO, EKS_CALCULATION.stMARA_EKS_ITEM.zArticleType, EKS_CALCULATION.stMARA_EKS_ITEM.DESCRIPTION_INT, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_ITEMNO, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.SK_DESCRIPTION_INT, SH.WHFACTOR, TR.DESCRIPTION, SH1.WHFACTOR, TR1.DESCRIPTION, SIGN_EA.SIGNSPECID, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.LISTINGOVERVIEWID, SUP.INTSUPPLIERNO, SUP.DESCRIPTION, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.ReceivingCountry, EKS_CALCULATION.stMARA_EKS_ITEM.zRelevantMDM, EKS_CALCULATION.xtEKS_BASICINFO_RecCountry.zIsWAWIRelevant, EKS_CALCULATION.stMARA_EKS_ITEM.zSource, EKS_CALCULATION.stMARA_EKS_ITEM.zActive
HAVING (SH1.WHFACTOR IS NULL) AND (SH.WHFACTOR IS NULL) AND (MIN(ITS.BESTBEFOREDATE) IS NULL) AND (MIN(ITS1.BESTBEFOREDATE) IS NULL) AND (ifnull(SIGN_EA.SIGNSPECID,0) <> 14)

);